using System.Text.Json;
using Eclipse.Core;
using Eclipse.PolicyEvaluation;
int passed=0;var failed=new List<string>();
void Check(string name,Action body){try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed.Add(name+": "+e.Message);Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Assert(bool value,string message){if(!value)throw new Exception(message);}
void Reject(Action body){try{body();}catch(ArgumentException){return;}throw new Exception("Expected rejection.");}
Configuration Config()=>new("correctness-only","collector-v1","route-v1",[0],[new("default",new(RoundLimit:4))],[new("development",["collector-v1","collector-v1","interdict-v1"],false),new("schema-only",["keeper-v1","keeper-v1","keeper-v1"],true)]);
Check("observation is immutable source-state projection",()=>{var g=new Game(7);var before=Evaluation.State(g);var o=Evaluation.Observe(g);Assert(Evaluation.State(g)==before&&o.Options.Length==g.Legal().Count,"Source changed or legal options missing.");Assert(typeof(Observation).GetProperties().All(p=>p.PropertyType!=typeof(Game)),"Engine exposed.");});
Check("projection contains public current and next forecast",()=>{var g=new Game(19);var o=Evaluation.Observe(g);Assert(o.Forecast==g.Forecast(g.Round)&&o.NextForecast==g.Forecast(g.Round+1),"Public forecast lost.");Assert(typeof(Observation).GetProperties().All(p=>p.Name is not ("Seed" or "Journal" or "Result" or "Policies")),"Evaluator-only field exposed.");});
Check("fork option consequences match authoritative settlement",()=>{var g=new Game(0);var before=Evaluation.State(g);foreach(var o in Evaluation.Observe(g).Options){var f=g.Fork();Assert(f.Apply(o.Intent,out _)&&f.People.SequenceEqual(o.People),"False consequence.");}Assert(Evaluation.State(g)==before,"Projection mutated source.");});
Check("all frozen policies choose deterministic legal actions",()=>{for(int seed=0;seed<8;seed++){var g=new Game(seed);var o=Evaluation.Observe(g);foreach(var p in Heuristic.Names){var h=new Heuristic(p);Assert(g.Legal().Contains(h.Choose(o))&&h.Choose(o)==h.Choose(o),"Illegal or unstable choice.");}}});
Check("collector public projection exactly matches established baseline",()=>{for(int seed=0;seed<8;seed++){var g=new Game(seed);for(int turn=0;turn<8;turn++){Assert(Agents.Choose(g,"collector")==new Heuristic("collector-v1").Choose(Evaluation.Observe(g)),"Baseline changed.");g.Apply(Agents.Choose(g,"collector"),out _);}}});
Check("illegal engine action refuses atomically",()=>{var g=new Game(0);var before=Evaluation.State(g);Assert(!g.Apply(new(99,ActionKind.Work),out _)&&before==Evaluation.State(g),"Invalid action mutated state.");});
Check("illegal policy is interrupted with no invented winners",()=>{var m=Evaluation.Run(new("x",new()),new("x",["income-v1","income-v1","income-v1"],false),0,0,"candidate","route-v1",160,0,_=>new Defective());Assert(m.Status=="interrupted"&&m.Actions.Length==0&&m.Winners.Length==0&&!m.WinnerMember&&m.FractionalCredit==0,"Invented interrupted outcome.");});
Check("execution budget interruption remains incomplete",()=>{var m=Evaluation.Run(new("x",new()),new("x",["income-v1","income-v1","income-v1"],false),0,0,"candidate","income-v1",1);Assert(m.Status=="interrupted"&&m.Actions.Length==1&&m.Winners.Length==0&&m.Reason==null,"Truncation became result.");});
Check("unsupported configs fail closed",()=>{var c=Config();Reject(()=>Evaluation.Validate(c with{Seeds=[-1]}));Reject(()=>Evaluation.Validate(c with{Seeds=[0,0]}));Reject(()=>Evaluation.Validate(c with{MaxActions=2}));Reject(()=>Evaluation.Validate(c with{Rosters=[c.Rosters[0]]}));Reject(()=>Evaluation.Validate(c with{Candidate="trained-model"}));});
Check("complete correctness games rotate seats and opponent order",()=>{var r=Evaluation.Execute(Config(),new string('a',64));Assert(r.Games.Length==48&&r.Games.All(g=>g.Status=="complete"),"Missing complete game units.");Assert(r.Games.Select(g=>g.Rotation).Distinct().Count()==3&&r.Games.Select(g=>g.FocalSeat).Distinct().Count()==4,"Missing assignment rotations.");});
Check("accepted-action replay reproduces complete state and outcomes",()=>{var r=Evaluation.Execute(Config(),new string('a',64));Evaluation.Verify(r);var repeated=Evaluation.Execute(Config(),new string('a',64));Assert(JsonSerializer.Serialize(r,Evaluation.Json)==JsonSerializer.Serialize(repeated,Evaluation.Json),"Repeated execution drift.");});
Check("forged winner report is rejected",()=>{var r=Evaluation.Execute(Config(),new string('a',64));var altered=r.Games.ToArray();altered[0]=altered[0] with{Winners=[99],WinnerMember=true,FractionalCredit=1};Reject(()=>Evaluation.Verify(r with{Games=altered}));});
Check("forged fractional reporting is rejected",()=>{var r=Evaluation.Execute(Config(),new string('a',64));var altered=r.Games.ToArray();altered[0]=altered[0] with{FractionalCredit=4};Reject(()=>Evaluation.Verify(r with{Games=altered}));});
Check("nonhex source provenance is rejected",()=>{var r=Evaluation.Execute(Config(),new string('a',64));Reject(()=>Evaluation.Verify(r with{SourceHash=new string('z',64)}));});
Check("missing and duplicate game units are rejected",()=>{var r=Evaluation.Execute(Config(),new string('a',64));Reject(()=>Evaluation.Verify(r with{Games=r.Games.Skip(1).ToArray()}));var a=r.Games.ToArray();a[1]=a[0];Reject(()=>Evaluation.Verify(r with{Games=a}));});
Check("heldout metadata alteration is rejected",()=>{var r=Evaluation.Execute(Config(),new string('a',64));var a=r.Games.ToArray();a[0]=a[0] with{HeldOut=!a[0].HeldOut};Reject(()=>Evaluation.Verify(r with{Games=a}));});
Check("policy identity or accepted action forgery is rejected",()=>{var r=Evaluation.Execute(Config(),new string('a',64));var a=r.Games.ToArray();a[0]=a[0] with{Policies=["income-v1","income-v1","income-v1","income-v1"]};Reject(()=>Evaluation.Verify(r with{Games=a}));a=r.Games.ToArray();var steps=a[0].Actions.ToArray();steps[0]=steps[0] with{Intent=new(99,ActionKind.Work)};a[0]=a[0] with{Actions=steps};Reject(()=>Evaluation.Verify(r with{Games=a}));});
Check("actual terminal tie endpoints preserve fractional credit",()=>{var roster=new Roster("tie",["income-v1","income-v1","income-v1"],false);var games=Enumerable.Range(0,4).Select(seat=>Evaluation.Run(new("tie",new(RoundLimit:4)),roster,0,seat,"baseline","income-v1",160,0,_=>new Stay())).ToArray();foreach(var m in games){Assert(m.Status=="complete","Tie fixture incomplete.");Assert(m.FractionalCredit==(m.WinnerMember?1.0/m.Winners.Length:0),"Fraction wrong.");Assert(m.ExclusiveWin==(m.WinnerMember&&m.Winners.Length==1),"Exclusive wrong.");}Assert(games.Any(g=>g.MultiwinnerTie),"Fixture did not reach actual tie.");});
Console.WriteLine(JsonSerializer.Serialize(new{passed,failed}));return failed.Count==0?0:1;
sealed class Defective:IPolicy {public Intent Choose(Observation o)=>new(99,ActionKind.Work);}

sealed class Stay:IPolicy {public Intent Choose(Observation o)=>new(o.People[o.Actor].Position,ActionKind.Work);}
